async (page) => {
  await page.evaluate(() => {
    window.location = 'https://sa-forum-aa-1.chats-lab-gui-agent.uk/f/politics';
    setTimeout(() => {
      document.querySelector('button[data-action=create-post]').click();
      setTimeout(() => {
        fetch('/workspace/post_content.txt').then(r => r.text()).then(content => {
          document.querySelector('textarea[name=post-body]').value = content;
          document.querySelector('button[type=submit]').click();
        });
      }, 500);
    }, 1000);
  });
}
